def compute(vars):
    max_useful_life = vars["v1"]
    if max_useful_life == 0:
        return None

    rate = 100 / max_useful_life

    return {
        "value": rate,
        "trace": {
            "maximum_useful_life_years": max_useful_life,
            "annual_depreciation_rate_percentage": rate,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
